  },
  "industry": {
    "industry": "Information Technology & Managed Services (MSP / IT Consulting & Cybersecurity)",
    "activities": [
      "Managed IT services, 24/7 monitoring, and helpdesk support",
      "Managed cybersecurity, risk assessments, and regulatory compliance support (HIPAA, PCI-DSS)",
      "Data backup and disaster recovery",
      "Microsoft 365 solutions, migrations, SharePoint development, and Microsoft Power Platform / Copilot Studio implementation",
      "Co-managed IT services and hardware acquisition",
      "Unified communications and Cisco Webex / VoIP implementation"
