    "claims": [
      {
        "statement": "Stability Networks provides managed IT support including server oversight, network administration, and proactive monitoring.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/",
        "quote": "Complete system management including server oversight, network administration, and proactive monitoring to prevent issues before they impact your operations."
      },
      {
        "statement": "The company designs, configures, and manages Microsoft 365 environments.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/",
        "quote": "Expert design, configuration, and management of your Microsoft 365 environment, including security structure for remote workers and data loss protection."
      },
      {
        "statement": "Stability Networks implements low-code applications, automated workflows, dashboards, and AI-powered chatbots using the Microsoft Power Platform.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/microsoft-power-platform/",
        "quote": "The Microsoft Power Platform is a low-code suite designed to help businesses build custom apps, automate manual processes, create dashboards, and even deploy AI-powered chatbots"
      },
      {
        "statement": "The company provides custom SharePoint development, intranet design, and workflow automation.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/sharepoint-development/",
        "quote": "At Stability Networks, we design and build SharePoint environments that fit your business perfectly."
      },
      {
        "statement": "Stability Networks offers consulting and implementation services for custom AI agents using Microsoft Copilot Studio.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/microsoft-365/how-copilot-studio-lets-your-business-build-custom-ai-agents-without-writing-code/",
        "quote": "Stability Networks can help map out where an agent makes sense for your business and build it correctly the first time."
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://stabilitynetworks.com/",
    "claims": [
      {
        "statement": "Stability Networks states that it supports IT for over 200 customers nationwide and monitors over 8,000 devices.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/about/",
        "quote": "Supports IT for over 200+ customers nationwide Over 8,000 devices under monitoring"
      },
      {
        "statement": "The company serves clients ranging from 10-user offices to multi-location enterprises across healthcare, finance, manufacturing, and professional services.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/managed-it-services/",
        "quote": "Our clients range from 10-user offices to multi-location enterprises."
      },
      {
        "statement": "Stability Networks markets IT services across Idaho (Meridian, Boise, Nampa, Sun Valley, Caldwell, Parma, Kuna, Middleton, Mountain Home, Twin Falls) and Salt Lake City, Utah.",
        "label": "inference",
        "sourceUrl": "https://stabilitynetworks.com/locations/",
        "quote": null
      },
      {
        "statement": "The company offers 24/7 after-hours emergency support for existing clients.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/contact/",
        "quote": "After-Hours Emergency 24/7, 365 days. Press “2” and leave a detailed message."
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The website privacy policy identifies the corporate legal entity as Stability Networks, Inc.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/privacy-policy/",
        "quote": "Identity of the controller: Stability Networks, Inc."
      },
      {
        "statement": "Stability Networks states that its team holds Microsoft Modern Workplace certifications and assists clients with HIPAA-HiTECH and PCI-DSS compliance.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/about/",
        "quote": "As Certified Microsoft 365 Modern Workplace certified experts, we ensure your data is protected with the latest cyber defense technology."
      },
      {
        "statement": "Stability Networks assists clients with federal and state regulatory compliance frameworks.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/about/",
        "quote": "Assist with Federal and State regulatory bodies, such as HIPAA-HiTECH, PCI-DSS, etc."
      }
    ],
    "limitations": "State corporate registration numbers, municipal business license numbers, and third-party verification of Microsoft partner certifications are not published on the company's website and could not be independently verified from public site pages alone."
  },
  "existingSoftware": [
    {
