    },
    {
      "product": "HubSpot",
      "purpose": "Marketing automation, CRM tracking, and analytics integration with WordPress",
      "evidence": {
        "statement": "The website loads HubSpot tracking scripts (js-na2.hs-scripts.com/242569938.js) integrated with WordPress.",
        "label": "inference",
        "sourceUrl": "https://stabilitynetworks.com/",
        "quote": null
