    },
    {
      "product": "WordPress (Flatsome Theme & Gravity Forms)",
      "purpose": "Content management system and web lead capture forms",
      "evidence": {
        "statement": "The site loads WordPress core scripts, the Flatsome theme, and Gravity Forms with Google reCAPTCHA on its contact page.",
        "label": "inference",
        "sourceUrl": "https://stabilitynetworks.com/contact/",
        "quote": null
